// Exact strings written by the operator or generated by the engine from such text alone.
// The miniGame projection shows them without a moderation round trip; resident input never enters this set.
import { L, placeDisplayName, placeDescription } from '../e2/lore/index.js';
import { publicLaw } from '../e2/engine/visibility.js';
import { VIRTUAL_CANON, VIRTUAL_CANON_P7 } from '../e2/p6/canon.js';
import { ROLE_SYSTEM_TEXTS, ROLE_SYSTEM_PATTERNS } from '../e2/p6/roles.js';

const EMPTY = Object.freeze({ texts: new Set(), patterns: [] });

function collect(out, value) {
  if (typeof value === 'string') { if (value.trim()) out.add(value); }
  else if (Array.isArray(value)) value.forEach(v => collect(out, v));
  else if (value && typeof value === 'object') Object.values(value).forEach(v => collect(out, v));
}

export function buildSystemTexts(rt) {
  const w = rt?.w;
  if (!w || rt.engine?.physics !== 2) return EMPTY;
  const texts = new Set();
  collect(texts, [L('zh').cityName, L('en').cityName, VIRTUAL_CANON, VIRTUAL_CANON_P7, ROLE_SYSTEM_TEXTS]);
  for (const p of Object.values(w.places || {})) {
    // A renamed or resident-founded place carries resident text; only untouched human places qualify.
    if (p.origin !== 'human' || p.renamedBy || p.razed) continue;
    collect(texts, [p.name, p.humanName, p.description]);
    for (const lang of ['zh', 'en']) collect(texts, [placeDisplayName(p, lang), placeDescription(p, lang).text]);
  }
  for (const law of Object.values(w.laws || {})) if (law.author === 'humans' && !law.proposalId) collect(texts, publicLaw(w, law.id));
  return { texts, patterns: ROLE_SYSTEM_PATTERNS };
}

/** Cached per world and tick: the set only changes when places are renamed or laws are replaced. */
export function systemTextSource(rt) {
  let key = null, value = EMPTY;
  return () => {
    const next = `${rt.w?.id}:${rt.w?.clock?.tick}`;
    if (next !== key) {
      try { value = buildSystemTexts(rt); } catch { value = EMPTY; }
      key = next;
    }
    return value;
  };
}
